targets.rawSql:
SELECT device AS metric,
       rct_battery_soc_ratio * 100 AS value,
       (cast(now() as long) / 1000000.0 - cast(timestamp as long) / 1000000.0) AS age_seconds
FROM ${table}
WHERE $__conditionalAll(device IN (${device:sqlstring}), $device)
LATEST ON timestamp PARTITION BY device;

SELECT sum(rct_solar_a_power_watts) AS value
FROM ${table}
WHERE $__conditionalAll(device IN (${device:sqlstring}), $device)
LATEST ON timestamp PARTITION BY device;

SELECT sum(rct_solar_b_power_watts) AS value
FROM ${table}
WHERE $__conditionalAll(device IN (${device:sqlstring}), $device)
LATEST ON timestamp PARTITION BY device;

SELECT sum(rct_household_load_power_watts) AS value
FROM ${table}
WHERE $__conditionalAll(device IN (${device:sqlstring}), $device)
LATEST ON timestamp PARTITION BY device;

SELECT sum(CASE WHEN rct_grid_power_watts < 0 THEN -rct_grid_power_watts ELSE 0 END) AS value
FROM (
  SELECT device, rct_grid_power_watts
  FROM ${table}
  WHERE $__conditionalAll(device IN (${device:sqlstring}), $device)
  LATEST ON timestamp PARTITION BY device
);

SELECT sum(CASE WHEN rct_grid_power_watts > 0 THEN rct_grid_power_watts ELSE 0 END) AS value
FROM (
  SELECT device, rct_grid_power_watts
  FROM ${table}
  WHERE $__conditionalAll(device IN (${device:sqlstring}), $device)
  LATEST ON timestamp PARTITION BY device
);

SELECT avg(rct_battery_soc_ratio) * 100 AS value
FROM ${table}
WHERE $__conditionalAll(device IN (${device:sqlstring}), $device)
LATEST ON timestamp PARTITION BY device;

SELECT avg(rct_battery_temperature_celsius) AS value
FROM ${table}
WHERE $__conditionalAll(device IN (${device:sqlstring}), $device)
LATEST ON timestamp PARTITION BY device;

SELECT max(rct_battery_cycles) AS value
FROM ${table}
WHERE $__conditionalAll(device IN (${device:sqlstring}), $device)
LATEST ON timestamp PARTITION BY device;

SELECT (sum(load_total) - sum(grid_load_total)) / sum(load_total) * 100 AS value
FROM (
  SELECT device,
         rct_energy_e_load_total_watt_hours AS load_total,
         rct_energy_grid_load_total_watt_hours AS grid_load_total
  FROM ${table}
  WHERE $__conditionalAll(device IN (${device:sqlstring}), $device)
  LATEST ON timestamp PARTITION BY device
);

SELECT sum(rct_energy_e_ac_total_sum) AS value
FROM (
  SELECT device, rct_energy_e_ac_total_sum
  FROM ${table}
  WHERE $__conditionalAll(device IN (${device:sqlstring}), $device)
  LATEST ON timestamp PARTITION BY device
);

SELECT sum(rct_energy_e_grid_feed_total_watt_hours) AS value
FROM (
  SELECT device, rct_energy_e_grid_feed_total_watt_hours
  FROM ${table}
  WHERE $__conditionalAll(device IN (${device:sqlstring}), $device)
  LATEST ON timestamp PARTITION BY device
);
